/**
 * Expansion Batch 24 (Issue #780; train spec T24-R1, generated by tools/train-kit; PROVISIONAL SPEC, ORIGINAL pizzadb.jp NOT CONFIRMED): the six ordinary recipes and eight materials of the Owner-approved T24-R1 packet
 * (docs/reports/data/TETO_T24-T26_PREP/T24-R1.preflight.md; Owner decisions 2026-11-10 and 2026-11-13). This file is the HAND-WRITTEN approval record of the train: the Owner-approved duplicate exceptions and the per-ID Research table are
 * written below by hand (never derived from the implementation); a measured value outside them is a STOP, never a test to edit.
 */
const NEW_IDS = ["diavola-pizza", "frutti-di-mare", "peruvian-aji-amarillo", "south-african-boerewors", "thai-chicken-pizza", "peking-duck-pizza"] as const;
const NEW_MATERIALS = ["aji-amarillo", "chutney", "cucumber", "peanut-sauce", "peking-duck", "spicy-salami", "squid", "sweet-bean-sauce"] as const;
const get = (id: string) => RECIPES.find((r) => r.id === id)! as Recipe;
const idsOf = (r: { requiredIngredients: readonly { ingredientId: string }[] }) => [...new Set(r.requiredIngredients.map((q) => q.ingredientId))];
/** The Duplicate Gate rule (the same as the staged / preflight gate, written out here by hand): identical, subset, superset, one differing ingredient at equal size, or Jaccard > 0.4. */
const duplicateKind = (a: readonly string[], b: readonly string[]): string | null => {
  const A = new Set(a);
  const B = new Set(b);
  const inter = [...A].filter((x) => B.has(x)).length;
  const jaccard = Math.round((inter / new Set([...A, ...B]).size) * 1000) / 1000;
  if (inter === A.size && inter === B.size) return "IDENTICAL";
  if (inter === A.size) return "SUBSET";
  if (inter === B.size) return "SUPERSET";
  if (A.size === B.size && A.size - inter === 1) return "ONE_DIFF";
  return jaccard > 0.4 ? "JACCARD_GT_0_4" : null;
};

describe("the six recipes (Owner-approved T24-R1 packet): composition in the sauce, cheese, toppings order, generic calibration, key-free, no CUT", () => {
  const SPEC: Record<string, readonly (readonly [string, number])[]> = {
    "diavola-pizza": [["tomato-sauce", 1], ["mozzarella", 3], ["spicy-salami", 2]],
    "frutti-di-mare": [["tomato-sauce", 1], ["clam", 2], ["mussel", 2], ["shrimp", 2], ["squid", 2]],
    "peruvian-aji-amarillo": [["aji-amarillo", 1], ["mozzarella", 3], ["black-olive", 2], ["chicken", 2]],
    "south-african-boerewors": [["chutney", 1], ["mozzarella", 3], ["onion", 2], ["sausage", 2]],
    "thai-chicken-pizza": [["peanut-sauce", 1], ["mozzarella", 3], ["chicken", 2], ["cilantro", 2]],
    "peking-duck-pizza": [["sweet-bean-sauce", 1], ["mozzarella", 3], ["cucumber", 2], ["green-onion", 2], ["peking-duck", 2]],
  };
  it.each(NEW_IDS.map((id) => [id]))("%s: the approved composition (the order puts the Rule W reserved ingredient last), PAINT sauce, bake 58-78, 100 Pitz, credited, no Lunch Rush", (id) => {
    const r = get(id);
    expect(r.requiredIngredients.map((q) => [q.ingredientId, q.minCount])).toEqual(SPEC[id]);
    expect(r.bakeTarget).toEqual({ start: 58, end: 78 });
    expect(r.baseRewardPitz).toBe(100);
    expect(r.lunchRush).toBe(false);
    expect(r.ladderCredit).not.toBe(false);
  });
  it("the Japanese names and descriptions are present and name no quantity or moment (Anti-Oracle)", () => {
    for (const id of NEW_IDS) {
      const r = get(id);
      expect(r.nameJa.length, id).toBeGreaterThan(0);
      expect(r.description, id).not.toMatch(/[0-9０-９]|[一二三四五六七八九十]個|分|秒|回/);
    }
  });
  it("frutti-di-mare is the shipped id of the staged frutti-di-mare-pizzadb (Owner-approved rename); no shipped id changes", () => {
    expect(RECIPES.some((r) => r.id === "frutti-di-mare")).toBe(true);
    expect(RECIPES.some((r) => (r.id as string) === "frutti-di-mare-pizzadb")).toBe(false);
  });
});

describe("Duplicate Gate (the GLOBAL 0.4 Jaccard guideline is NOT changed): exactly the Owner-approved D-1 exceptions of the T24-R1 packet, nothing else", () => {
  // Hand-written approval record (packet section 3, Owner 2026-11-10): partner -> the reason it was flagged. A new partner, or a missing one, is a STOP.
  const APPROVED_PARTNERS: Record<string, readonly string[]> = {
    "diavola-pizza": ["bismarck", "funghi", "margherita", "pepperoni", "salsiccia"], // ONE_DIFF (Jaccard 0.5 each)
    "frutti-di-mare": ["pescatore"], // Jaccard 0.5
    "peruvian-aji-amarillo": [],
    "south-african-boerewors": ["polish-kielbasa", "spanish-chorizo-pizza"], // ONE_DIFF (Jaccard 0.6 each)
    "thai-chicken-pizza": ["bbq-chicken-pizza", "reina-pepiada-pizza"], // Jaccard 0.5 / 0.429
    "peking-duck-pizza": [],
  };
  it.each(NEW_IDS.map((id) => [id]))("%s: the flagged partners (identical / subset / superset / one-ingredient difference / Jaccard > 0.4) are exactly the approved ones", (id) => {
    const mine = idsOf(get(id));
    const flagged = (RECIPES as readonly Recipe[]).filter((o) => o.id !== id && duplicateKind(mine, idsOf(o)) !== null).map((o) => o.id as string).sort();
    expect(flagged).toEqual([...APPROVED_PARTNERS[id]].sort());
  });
});

describe("the ladder: six ordinary steps 75-80 (derived, in the REC-04 order), no star gate, the batch manifest", () => {
  const steps = DISCOVERY_LADDER.steps;
  it("the steps and their keys", () => {
    expect(ordinaryLadderSteps(steps)).toHaveLength(80);
    expect(steps.slice(74, 80).map((s) => [s.step, s.ingredientIds, s.keyRecipeId])).toEqual([
      [75, ["spicy-salami"], "diavola-pizza"],
      [76, ["squid"], "frutti-di-mare"],
      [77, ["aji-amarillo"], "peruvian-aji-amarillo"],
      [78, ["chutney"], "south-african-boerewors"],
      [79, ["peanut-sauce"], "thai-chicken-pizza"],
      [80, ["cucumber", "peking-duck", "sweet-bean-sauce"], "peking-duck-pizza"],
    ]);
    for (const s of steps.slice(74, 80)) expect((s as { starGates?: unknown }).starGates, `step ${s.step}`).toBeUndefined();
  });
  it("every other ingredient of each recipe is owned before its step (the new materials are unlocked at their own step)", () => {
    for (const id of NEW_IDS) {
      const stepNo = steps.find((s) => s.keyRecipeId === id)!.step;
      const before = new Set<string>(steps.slice(0, stepNo - 1).flatMap((s) => s.ingredientIds as readonly string[]));
      const here = new Set<string>(steps[stepNo - 1].ingredientIds as readonly string[]);
      for (const q of get(id).requiredIngredients) if (!["tomato-sauce", "mozzarella", "basil"].includes(q.ingredientId)) expect(before.has(q.ingredientId) || here.has(q.ingredientId), `${id}/${q.ingredientId}`).toBe(true);
    }
  });
  it("the batch manifest is LANDED and consistent: appended tail, append-only ladder, chapter / cohort identity, explicit declarations", () => {
    expect(B24_BATCH.recipes.map((r) => r.recipeId)).toEqual([...NEW_IDS]);
    expect(validateBatchManifest(B24_BATCH, ordinaryCatalogView())).toEqual([]);
  });
  it("the eight new materials exist and each is used by a new recipe", () => {
    for (const m of NEW_MATERIALS) expect(NEW_IDS.some((id) => idsOf(get(id)).includes(m)), m).toBe(true);
  });
});

describe("Research (Owner-approved per ID, T24-R1 packet section 4): the canonical order changes 0 letters; the non-canonical changes are exactly the 43 approved IDs within their approved stage and shift", () => {
  // Hand-written approval record (never derived): the 43 shipped IDs, each with its approved shape. `(none)->A` = a new first letter only; the second kind may also
  // gain B or move one letter later; the third kind may gain up to C or move up to two letters later.
  const FIRST_LETTER_ONLY: readonly string[] = ["aussie", "baingan-bharta-pizza", "bbq-chicken-pizza", "brazilian-calabresa", "buffalo-chicken", "capricciosa", "full-english-pizza", "jamaican-jerk-chicken-pizza", "new-haven-apizza", "nigerian-suya-pizza", "pesto-tonno", "pizza-portuguesa", "polish-kielbasa", "puttanesca-pizza", "reina-pepiada-pizza", "rendang-pizza", "salsiccia", "sichuan-eggplant-pizza"];
  const FIRST_LETTER_OR_ONE_LATER: readonly string[] = ["bacalhau", "boscaiola", "calabresa-argentina", "flammkuchen", "fugazza", "goulash-pizza", "meat-lovers", "palmito-pizza", "pescatore", "pesto-gamberi", "pizza-feta-eliniki", "pizza-finocchi-salad", "pizza-moscow", "salsiccia-e-friarielli", "spanish-chorizo-pizza", "supreme-pizza", "tandoori-paneer-pizza", "tonno-e-cipolla", "veggie-supreme-pizza", "vongole", "wasabi-beef-pizza", "yuzu-shrimp-pizza"];
  const FIRST_LETTER_UP_TO_C_OR_TWO_LATER: readonly string[] = ["curry-pizza-japan", "frango-catupiry", "pesto-pollo"];
  const changes = researchLetterChangesAcrossOrders(NEW_IDS, RECIPES as never, 40, 20261105);
  const changed = [...changes.keys()].sort();
  const code = (l: string) => l.charCodeAt(0) - 64;
  it("the canonical ladder order changes no pre-existing letter (the full late catalog included)", () => {
    expect([...changes.values()].flat().filter((c) => c.canonical)).toEqual([]);
  });
  it("every measured ID is one of the approved 43 (the approval is a deterministic UPPER bound over the acquisition orders; the seeded audit samples 40 random orders, so it may see fewer, never another ID)", () => {
    const approved = [...FIRST_LETTER_ONLY, ...FIRST_LETTER_OR_ONE_LATER, ...FIRST_LETTER_UP_TO_C_OR_TWO_LATER].sort();
    expect(approved).toHaveLength(43);
    expect(new Set(approved).size).toBe(43);
    expect(changed.filter((id) => !approved.includes(id))).toEqual([]);
    expect(changed.length).toBeGreaterThan(30); // the sampled audit still reaches most of the approved set
  });
  it("every measured letter change stays within its ID's approved shape (a different change is a STOP)", () => {
    for (const [id, list] of changes) {
      for (const c of list) {
        const m = /^(-|[A-Z]+)->([A-Z]+)$/.exec(c.change);
        expect(m, `${id} ${c.change}`).not.toBeNull();
        const [, from, to] = m!;
        if (FIRST_LETTER_ONLY.includes(id)) {
          expect([from, to], id).toEqual(["-", "A"]);
        } else if (FIRST_LETTER_OR_ONE_LATER.includes(id)) {
          if (from === "-") expect(["A", "B"], id).toContain(to);
          else expect(code(to) - code(from), id).toBe(1);
        } else {
          expect(FIRST_LETTER_UP_TO_C_OR_TWO_LATER, id).toContain(id);
          if (from === "-") expect(["A", "B", "C"], id).toContain(to);
          else expect([1, 2], id).toContain(code(to) - code(from));
        }
      }
    }
  });
});
